    const int width = std::min(block, n - 2 - start);
    const int tail = start + 1;
    auto panel = reflectors.slice(1, tail, n).slice(
        2, start, start + width);
    auto v = panel.tril(-1);
    v.diagonal(0, 1, 2).fill_(1.0);
    auto gram = at::bmm(v.transpose(1, 2), v);
    auto panel_taus = taus.slice(1, start, start + width).contiguous();
    auto t = compact_wy_t(gram, panel_taus);
    auto panel_vectors = vectors.slice(1, tail, n);
    auto projected = at::bmm(v.transpose(1, 2), panel_vectors);
    projected = at::bmm(t, projected);
    panel_vectors.sub_(at::bmm(v, projected));
  }

  auto gram = at::bmm(vectors.transpose(1, 2), vectors);
  gram.mul_(-0.5);
  gram.diagonal(0, 1, 2).add_(1.5);
  vectors = at::bmm(vectors, gram);
  auto flags = certify_eigh(input, vectors, values);
  auto unsafe_indices = at::nonzero(
      flags.narrow(0, 0, batch)).flatten();
  if (unsafe_indices.numel() == 0) {
    return {vectors, values};
  }

  auto candidate_data = at::index_select(
      input, 0, unsafe_indices).contiguous();
  auto candidate_vectors = at::index_select(
      vectors, 0, unsafe_indices).contiguous();
  auto candidate_values = at::index_select(
      values, 0, unsafe_indices).contiguous();
  gram = at::bmm(candidate_vectors.transpose(1, 2), candidate_vectors);
  gram.mul_(-0.5);
  gram.diagonal(0, 1, 2).add_(1.5);
  candidate_vectors = at::bmm(candidate_vectors, gram);
  auto refined_flags = certify_eigh(
      candidate_data, candidate_vectors, candidate_values);
  vectors.index_copy_(0, unsafe_indices, candidate_vectors);

  auto remaining_positions = at::nonzero(
      refined_flags.narrow(0, 0, unsafe_indices.numel())).flatten();
  if (remaining_positions.numel() == 0) {
    return {vectors, values};
  }
  auto remaining_indices = at::index_select(
      unsafe_indices, 0, remaining_positions);
  if (remaining_indices.numel() * 4 >= batch * 3) {
    return xsyev_batched(input);
