        matrix.data_ptr<float>(), panel_v.data_ptr<float>(),
        panel_w.data_ptr<float>(), reflectors.data_ptr<float>(),
        diagonal.data_ptr<float>(), off_diagonal.data_ptr<float>(),
        taus.data_ptr<float>(), static_cast<int>(start),
        static_cast<int>(width));
  } else {
    cudaFuncSetAttribute(sytrd_panel_kernel<n, kPanelWidth, false>,
                         cudaFuncAttributeMaxDynamicSharedMemorySize,
                         shared_bytes);
    sytrd_panel_kernel<n, kPanelWidth, false><<<batch, 512, shared_bytes>>>(
        matrix.data_ptr<float>(), panel_v.data_ptr<float>(),
        panel_w.data_ptr<float>(), reflectors.data_ptr<float>(),
        diagonal.data_ptr<float>(), off_diagonal.data_ptr<float>(),
        taus.data_ptr<float>(), static_cast<int>(start),
        static_cast<int>(width));
  }
  return {panel_v, panel_w};
}

